-- VD-3: dispatch of completed contract documents.  This deliberately does not
-- reuse kommunikationsvorgang.mail_*: a contract dispatch has many recipients,
-- immutable attachments and independently retryable delivery attempts.

-- „vertragsversand“ is deliberately not seeded onto an existing function.  It
-- must be assigned explicitly in the central club-function administration.

create table public.vertragsversand_vertragspartei_snapshot (
  kommunikationsvorgang_id bigint not null references public.kommunikationsvorgang(id) on delete restrict,
  revision integer not null,
  rolle text not null check (rolle in ('hauptmitglied','nebenmitglied','gesetzliche_vertretung','antragsteller','paechter_1','paechter_2')),
  mitglied_id bigint references public.mitglied(id) on delete restrict,
  name_snapshot text not null,
  quelle text not null,
  primary key (kommunikationsvorgang_id, revision, rolle)
);
create table public.vertragsversand_anlage_snapshot (
  id bigint generated by default as identity primary key,
  kommunikationsvorgang_id bigint not null,
  revision integer not null,
  sortierung smallint not null,
  art text not null check (art in ('vertrag','anlage')),
  bindungsstatus text not null default 'digital_gebunden' check (bindungsstatus in ('digital_gebunden','papier_ausgehaendigt')),
  dokumenttyp_code text,
  dokument_id bigint references public.dokument(id) on delete restrict,
  vereinsdokument_fassung_id bigint references public.vereinsdokument_fassung(id) on delete restrict,
  bezeichnung_snapshot text not null,
  dateiname_snapshot text,
  mime_type_snapshot text,
  bucket_snapshot text,
  storage_path_snapshot text,
  drive_file_id_snapshot text,
  sha256_snapshot text,
  bereitgestellt_am_snapshot timestamptz,
  bemerkung_snapshot text,
  constraint vertragsversand_anlage_snapshot_uq unique (kommunikationsvorgang_id, revision, sortierung),
  constraint vertragsversand_anlage_snapshot_source_chk check ((art='vertrag' and bindungsstatus='digital_gebunden' and dokument_id is not null and vereinsdokument_fassung_id is null and storage_path_snapshot is not null) or (art='anlage' and vereinsdokument_fassung_id is not null and ((bindungsstatus='digital_gebunden' and storage_path_snapshot is not null and dateiname_snapshot is not null) or (bindungsstatus='papier_ausgehaendigt' and dokument_id is null and storage_path_snapshot is null and dateiname_snapshot is null))))
);
-- An attachment snapshot belongs to the whole contract revision, while one
-- revision may intentionally contain several party rows.  Therefore a normal
-- foreign key to only (kommunikationsvorgang_id, revision) would be invalid.
-- A deferred constraint trigger preserves the intended invariant instead:
-- at transaction end every attachment snapshot must have at least one party
-- snapshot for the same contract revision.
create or replace function public.guard_vertragsversand_anlage_party_snapshot()
returns trigger
language plpgsql
security definer
set search_path=public,pg_temp
as $$
begin
  if not exists (
    select 1
    from public.vertragsversand_vertragspartei_snapshot p
    where p.kommunikationsvorgang_id = new.kommunikationsvorgang_id
      and p.revision = new.revision
  ) then
    raise exception
      'Vertragsversand-Anlage benötigt mindestens einen Vertragspartei-Snapshot'
      using errcode='23503';
  end if;

  return new;
end;
$$;
create constraint trigger trg_vertragsversand_anlage_party_snapshot
after insert or update
on public.vertragsversand_anlage_snapshot
deferrable initially deferred
for each row
execute function public.guard_vertragsversand_anlage_party_snapshot();
-- A legal representative without a member record still has a named party
-- snapshot, but cannot become a mail recipient.

create table public.versandinstanz (
  id bigint generated by default as identity primary key,
  kommunikationsvorgang_id bigint not null references public.kommunikationsvorgang(id) on delete restrict,
  revision integer not null,
  vertragsart text not null check (vertragsart in ('mitgliedsantrag','pachtvertrag','wartungsvertrag','wartungsvertrag_verlaengerung')),
  status text not null default 'bereit' check (status in ('bereit','wird_versendet','teilweise_fehlerhaft','versendet','fehler')),
  betreff_snapshot text not null,
  text_snapshot text not null,
  idempotenzschluessel uuid not null default gen_random_uuid() unique,
  erneuter_versand_von_id bigint references public.versandinstanz(id) on delete restrict,
  erstellt_am timestamptz not null default now(), erstellt_von uuid not null default auth.uid(),
  beansprucht_am timestamptz, beansprucht_von uuid, versendet_am timestamptz, letzter_fehler text
);
create index ix_versandinstanz_vorgang on public.versandinstanz(kommunikationsvorgang_id, revision, erstellt_am desc);
create table public.versandinstanz_empfaenger_snapshot (
  id bigint generated by default as identity primary key,
  versandinstanz_id bigint not null references public.versandinstanz(id) on delete restrict,
  rolle text not null,
  mitglied_id bigint references public.mitglied(id) on delete restrict,
  name_snapshot text not null,
  email_snapshot text,
  email_normalisiert text,
  einwilligung_info_snapshot boolean not null default false,
  einwilligung_rechnung_snapshot boolean not null default false,
  versand_erlaubt boolean not null,
  nicht_versandfaehig_grund text,
  status text not null default 'bereit' check (status in ('bereit','versendet','fehler','nicht_versandfaehig')),
  versendet_am timestamptz, letzter_fehler text,
  constraint versandinstanz_empfaenger_uq unique(versandinstanz_id, rolle)
);
create table public.versandinstanz_dokument_snapshot (
  versandinstanz_id bigint not null references public.versandinstanz(id) on delete restrict,
  sortierung smallint not null, bezeichnung_snapshot text not null, bindungsstatus text not null check(bindungsstatus in ('digital_gebunden','papier_ausgehaendigt')),
  dateiname_snapshot text, mime_type_snapshot text, bucket_snapshot text, storage_path_snapshot text,
  drive_file_id_snapshot text, sha256_snapshot text, dokumenttyp_code text, bereitgestellt_am_snapshot timestamptz, bemerkung_snapshot text,
  primary key(versandinstanz_id, sortierung)
);
create table public.versandinstanz_versuch (
  id bigint generated by default as identity primary key,
  versandinstanz_id bigint not null references public.versandinstanz(id) on delete restrict,
  empfaenger_snapshot_id bigint not null references public.versandinstanz_empfaenger_snapshot(id) on delete restrict,
  gestartet_am timestamptz not null default now(), abgeschlossen_am timestamptz,
  status text not null check(status in ('gestartet','versendet','fehler')), smtp_message_id text, smtp_antwort jsonb, fehlertext text
);
create or replace function public.resolve_vertragsversand_berechtigte(p_stichtag date default current_date)
returns table(mitglied_id bigint) language sql stable security definer set search_path=public,pg_temp as $$
 with basis as (select b.id,b.mitglied_id from public.vereinsfunktion_verwendung u join public.vereinsfunktion f on f.id=u.vereinsfunktion_id and f.aktiv join public.vereinsfunktion_besetzung b on b.vereinsfunktion_id=f.id where u.verwendungszweck='vertragsversand' and b.gueltig_ab<=p_stichtag and (b.gueltig_bis is null or b.gueltig_bis>=p_stichtag)), reps as (select b.id,rb.mitglied_id from basis b join public.vereinsfunktion_vertretung v on v.vertretene_besetzung_id=b.id and v.gueltig_ab<=p_stichtag and (v.gueltig_bis is null or v.gueltig_bis>=p_stichtag) join public.vereinsfunktion_besetzung rb on rb.id=v.vertreter_besetzung_id and rb.gueltig_ab<=p_stichtag and (rb.gueltig_bis is null or rb.gueltig_bis>=p_stichtag))
 select b.mitglied_id from basis b where not exists(select 1 from reps r where r.id=b.id) union select mitglied_id from reps;
$$;
create or replace function public.kann_vertragsversand_ausfuehren()
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select auth.role()='service_role' or exists(select 1 from public.app_user a join public.resolve_vertragsversand_berechtigte(current_date) x on x.mitglied_id=a.mitglied_id where a.user_id=auth.uid());
$$;
create or replace function public.ensure_vertragsversand_snapshot(p_kommunikationsvorgang_id bigint)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.kommunikationsvorgang%rowtype; d public.dokument%rowtype; r record; i smallint:=1; e jsonb; typ text;
begin
 select * into v from public.kommunikationsvorgang where id=p_kommunikationsvorgang_id for key share;
 if not found or v.final_dokument_id is null or v.dokumenttyp not in ('mitgliedsantrag','pachtvertrag','wartungsvertrag','wartungsvertrag_verlaengerung') then raise exception 'Kein versandfähiger finaler Vertragsvorgang' using errcode='23514'; end if;
 select * into d from public.dokument where id=v.final_dokument_id and archiviert_at is null;
 if not found or d.source_kommunikationsvorgang_id is distinct from v.id or d.source_revision is distinct from coalesce(v.signatur_revision,v.revision) then raise exception 'Finaldokument-Provenance fehlt' using errcode='23514'; end if;
 insert into public.vertragsversand_vertragspartei_snapshot(kommunikationsvorgang_id,revision,rolle,mitglied_id,name_snapshot,quelle)
 select v.id,coalesce(v.signatur_revision,v.revision),case when p.signatur_schluessel in ('member.application','mitglied','lease.member') then 'hauptmitglied' when p.signatur_schluessel='lease.second_party' then 'paechter_2' when p.signatur_schluessel like 'nebenmitglied.%' then 'nebenmitglied' else 'gesetzliche_vertretung' end,p.mitglied_id,coalesce(nullif(btrim(p.unterzeichner_name_snapshot),''),'Unbekannte Person'),'prepared_contract_signatur'
 from public.prepared_contract_signatur p where p.kommunikationsvorgang_id=v.id and p.signatur_revision=coalesce(v.signatur_revision,v.revision) and p.status='unterschrieben' and p.unterzeichner_typ<>'vereinsunterzeichner' and p.signatur_schluessel in ('member.application','mitglied','lease.member','lease.second_party','nebenmitglied.antrag','gesetzliche_vertretung.antrag')
 on conflict do nothing;
 if not exists(select 1 from public.vertragsversand_vertragspartei_snapshot where kommunikationsvorgang_id=v.id and revision=coalesce(v.signatur_revision,v.revision)) then
   insert into public.vertragsversand_vertragspartei_snapshot values(v.id,coalesce(v.signatur_revision,v.revision),'hauptmitglied',v.mitglied_id,coalesce((select nullif(btrim(concat_ws(' ',m.vorname,m.name)),'') from public.mitglied m where m.id=v.mitglied_id),'Mitglied #'||v.mitglied_id),'vorgang') on conflict do nothing;
 end if;
 insert into public.vertragsversand_anlage_snapshot(kommunikationsvorgang_id,revision,sortierung,art,dokument_id,bezeichnung_snapshot,dateiname_snapshot,mime_type_snapshot,bucket_snapshot,storage_path_snapshot,drive_file_id_snapshot)
 values(v.id,coalesce(v.signatur_revision,v.revision),0,'vertrag',d.id,coalesce(d.titel,'Vertragsdokument'),coalesce(d.dateiname,'vertrag.pdf'),coalesce(d.mime_type,'application/pdf'),coalesce(d.bucket,'dokumente'),coalesce(d.storage_path,''),d.drive_file_id) on conflict do nothing;
 if not exists(select 1 from public.vertragsversand_anlage_snapshot where kommunikationsvorgang_id=v.id and revision=coalesce(v.signatur_revision,v.revision) and sortierung=0 and length(storage_path_snapshot)>0 and drive_file_id_snapshot is not null) then raise exception 'Finaldokument ist nicht sicher abrufbar' using errcode='23514'; end if;
 foreach typ in array case when v.dokumenttyp='mitgliedsantrag' then array['satzung']::text[] when v.dokumenttyp='pachtvertrag' then array['kleingartenordnung','beitragsordnung','arbeitsordnung']::text[] else array[]::text[] end loop
   select value into e from jsonb_array_elements(coalesce(v.entwurf_daten->'vereinsunterlagenNachweis',v.entwurf_daten->'VereinsunterlagenNachweis','[]'::jsonb)) value where value->>'dokumenttyp'=typ limit 1;
   if e is null then raise exception 'Pflichtanlage % ist weder digital gebunden noch als Papierübergabe dokumentiert',typ using errcode='23514'; end if;
   select * into r from public.vereinsdokument_fassung f where f.id=nullif(e->>'vereinsdokument_fassung_id','')::bigint and f.dokumenttyp_code=typ;
   if not found then raise exception 'Die dokumentierte Fassung für Pflichtanlage % fehlt',typ using errcode='23514'; end if;
   if e->>'bereitstellungsart'='papier' then
     insert into public.vertragsversand_anlage_snapshot(kommunikationsvorgang_id,revision,sortierung,art,bindungsstatus,dokumenttyp_code,vereinsdokument_fassung_id,bezeichnung_snapshot,bemerkung_snapshot,bereitgestellt_am_snapshot) values(v.id,coalesce(v.signatur_revision,v.revision),i,'anlage','papier_ausgehaendigt',typ,r.id,typ||' – Fassung '||r.fassung, nullif(e->>'bemerkung',''),nullif(e->>'bereitgestellt_am','')::timestamptz) on conflict do nothing;
   elsif e->>'bereitstellungsart'='digital' and r.storage_path is not null and r.dateiname is not null and r.sha256 is not null then
     insert into public.vertragsversand_anlage_snapshot(kommunikationsvorgang_id,revision,sortierung,art,bindungsstatus,dokumenttyp_code,vereinsdokument_fassung_id,bezeichnung_snapshot,dateiname_snapshot,mime_type_snapshot,bucket_snapshot,storage_path_snapshot,sha256_snapshot,bereitgestellt_am_snapshot) values(v.id,coalesce(v.signatur_revision,v.revision),i,'anlage','digital_gebunden',typ,r.id,typ||' – Fassung '||r.fassung,r.dateiname,'application/pdf','vereinsregelwerke',r.storage_path,r.sha256,nullif(e->>'bereitgestellt_am','')::timestamptz) on conflict do nothing;
   else raise exception 'Pflichtanlage % ist weder digital gebunden noch als Papierübergabe dokumentiert',typ using errcode='23514'; end if;
   i:=i+1;
 end loop;
end; $$;
create or replace function public.freeze_vertragsversand_snapshot() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if new.final_dokument_id is not null and new.final_dokument_id is distinct from old.final_dokument_id and new.dokumenttyp in ('mitgliedsantrag','pachtvertrag','wartungsvertrag','wartungsvertrag_verlaengerung') then
    perform public.ensure_vertragsversand_snapshot(new.id);
  end if;
  return new;
end; $$;
drop trigger if exists trg_freeze_vertragsversand_snapshot on public.kommunikationsvorgang;
create trigger trg_freeze_vertragsversand_snapshot after update of final_dokument_id on public.kommunikationsvorgang for each row execute function public.freeze_vertragsversand_snapshot();
create or replace function public.vertragsversand_mailtext_snapshot()
returns text language plpgsql stable security definer set search_path=public,pg_temp as $$
declare c record; vorstand text;
begin
 select * into c from public.vereinskonfiguration where aktiv order by updated_at desc,id desc limit 1;
 select string_agg(concat_ws(' ',bezeichnung,concat_ws(' ',vorname,nachname)), E'\n' order by ist_hauptkontakt desc,gruppen_sort_order,besetzung_id) into vorstand from public.impressum_kontakte();
 return E'Guten Tag,\n\nim Anhang erhalten Sie wichtige Unterlagen zu Ihrer Mitgliedschaft bzw. Ihrem Vertragsverhältnis im Kleingartenverein.\n\nBitte beachten Sie: Diese E-Mail und ihre Anhänge können vertrauliche und personenbezogene Informationen enthalten und sind ausschließlich für die vorgesehenen Empfänger bestimmt. Sollten Sie diese E-Mail irrtümlich erhalten haben, informieren Sie uns bitte und löschen Sie die Nachricht sowie die Anhänge.\n\nMit freundlichen Grüßen\n\n'||coalesce(nullif(c.vereinsname,''),'KGV Oberrothenbach e.V.')||E'\n'||coalesce(nullif(concat_ws(', ',c.strasse,concat_ws(' ',c.plz,c.ort)),''),'')||case when nullif(vorstand,'') is null then '' else E'\nVertretungsberechtigt:\n'||vorstand end||case when nullif(c.registerangabe,'') is null then '' else E'\n'||c.registerangabe end||case when nullif(c.standard_email,'') is null then '' else E'\n'||c.standard_email end;
end; $$;
create or replace function public.prepare_contract_dispatch(p_kommunikationsvorgang_id bigint,p_erneuter_versand_von_id bigint default null)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.kommunikationsvorgang%rowtype; x bigint; p record; allowed boolean; reason text;
begin
 if not public.kann_vertragsversand_ausfuehren() then raise exception 'Keine Berechtigung für Vertragsversand' using errcode='42501'; end if;
 select * into v from public.kommunikationsvorgang where id=p_kommunikationsvorgang_id for update;
 if not found or v.final_dokument_id is null or v.status<>'erledigt' or v.dokumenttyp not in ('mitgliedsantrag','pachtvertrag','wartungsvertrag','wartungsvertrag_verlaengerung') then raise exception 'Vertragsvorgang ist noch nicht abgeschlossen' using errcode='23514'; end if;
 perform public.ensure_vertragsversand_snapshot(v.id);
 if p_erneuter_versand_von_id is not null and not exists(select 1 from public.versandinstanz z where z.id=p_erneuter_versand_von_id and z.status='versendet' and z.kommunikationsvorgang_id=v.id and z.revision=coalesce(v.signatur_revision,v.revision)) then raise exception 'Erneuter Versand muss auf einen erfolgreichen Versand desselben Vertragsstands verweisen' using errcode='23514'; end if;
 insert into public.versandinstanz(kommunikationsvorgang_id,revision,vertragsart,betreff_snapshot,text_snapshot,erneuter_versand_von_id) values(v.id,coalesce(v.signatur_revision,v.revision),v.dokumenttyp,'Wichtige Unterlagen zu Ihrer Mitgliedschaft im Kleingartenverein',public.vertragsversand_mailtext_snapshot(),p_erneuter_versand_von_id) returning id into x;
 for p in select s.*,m.email,m.email_info_einwilligung,m.email_rechnung_einwilligung from public.vertragsversand_vertragspartei_snapshot s left join public.mitglied m on m.id=s.mitglied_id where s.kommunikationsvorgang_id=v.id and s.revision=coalesce(v.signatur_revision,v.revision) loop
   allowed:=p.email is not null and btrim(p.email)~*'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' and (coalesce(p.email_info_einwilligung,false) or coalesce(p.email_rechnung_einwilligung,false)); reason:=case when p.email is null or btrim(p.email)='' then 'Keine E-Mail-Adresse' when not (coalesce(p.email_info_einwilligung,false) or coalesce(p.email_rechnung_einwilligung,false)) then 'Keine E-Mail-Einwilligung' when not btrim(p.email)~*'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then 'Ungültige E-Mail-Adresse' else null end;
   insert into public.versandinstanz_empfaenger_snapshot(versandinstanz_id,rolle,mitglied_id,name_snapshot,email_snapshot,email_normalisiert,einwilligung_info_snapshot,einwilligung_rechnung_snapshot,versand_erlaubt,nicht_versandfaehig_grund,status) values(x,p.rolle,p.mitglied_id,p.name_snapshot,p.email,lower(btrim(p.email)),coalesce(p.email_info_einwilligung,false),coalesce(p.email_rechnung_einwilligung,false),allowed,reason,case when allowed then 'bereit' else 'nicht_versandfaehig' end);
 end loop;
 if not exists(select 1 from public.versandinstanz_empfaenger_snapshot where versandinstanz_id=x and versand_erlaubt) then raise exception 'Kein Empfänger mit gültiger E-Mail-Einwilligung' using errcode='23514'; end if;
 insert into public.versandinstanz_dokument_snapshot select x,sortierung,bezeichnung_snapshot,bindungsstatus,dateiname_snapshot,mime_type_snapshot,bucket_snapshot,storage_path_snapshot,drive_file_id_snapshot,sha256_snapshot,dokumenttyp_code,bereitgestellt_am_snapshot,bemerkung_snapshot from public.vertragsversand_anlage_snapshot where kommunikationsvorgang_id=v.id and revision=coalesce(v.signatur_revision,v.revision);
 return x;
end; $$;
create or replace function public.create_contract_redispatch(p_versandinstanz_id bigint)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare z public.versandinstanz%rowtype;
begin
 if not public.kann_vertragsversand_ausfuehren() then raise exception 'Keine Berechtigung für Vertragsversand' using errcode='42501'; end if;
 select * into z from public.versandinstanz where id=p_versandinstanz_id and status='versendet' for key share;
 if not found then raise exception 'Erneut senden ist nur nach erfolgreichem Versand möglich' using errcode='23514'; end if;
 return public.prepare_contract_dispatch(z.kommunikationsvorgang_id,z.id);
end; $$;
create or replace function public.claim_contract_dispatch(p_versandinstanz_id bigint)
returns table(id bigint,betreff text,mailtext text) language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if not public.kann_vertragsversand_ausfuehren() then raise exception 'Keine Berechtigung für Vertragsversand' using errcode='42501'; end if;
 update public.versandinstanz set status='wird_versendet',beansprucht_am=now(),beansprucht_von=auth.uid(),letzter_fehler=null where id=p_versandinstanz_id and status in ('bereit','fehler','teilweise_fehlerhaft') and exists(select 1 from public.versandinstanz_empfaenger_snapshot e where e.versandinstanz_id=p_versandinstanz_id and e.status in ('bereit','fehler')) returning versandinstanz.id,betreff_snapshot,text_snapshot into id,betreff,mailtext;
 if not found then raise exception 'Versandinstanz ist nicht beanspruchbar' using errcode='40001'; end if; return next;
end; $$;
alter table public.versandinstanz enable row level security;
alter table public.versandinstanz_empfaenger_snapshot enable row level security;
alter table public.versandinstanz_dokument_snapshot enable row level security;
alter table public.versandinstanz_versuch enable row level security;
alter table public.vertragsversand_vertragspartei_snapshot enable row level security;
alter table public.vertragsversand_anlage_snapshot enable row level security;
create policy versandinstanz_read on public.versandinstanz for select to authenticated using(public.kann_vertragsversand_ausfuehren());
create policy versandinstanz_empfaenger_read on public.versandinstanz_empfaenger_snapshot for select to authenticated using(public.kann_vertragsversand_ausfuehren());
create policy versandinstanz_dokument_read on public.versandinstanz_dokument_snapshot for select to authenticated using(public.kann_vertragsversand_ausfuehren());
create policy versandinstanz_versuch_read on public.versandinstanz_versuch for select to authenticated using(public.kann_vertragsversand_ausfuehren());
create policy vertragsversand_partei_read on public.vertragsversand_vertragspartei_snapshot for select to authenticated using(public.kann_vertragsversand_ausfuehren());
create policy vertragsversand_anlage_read on public.vertragsversand_anlage_snapshot for select to authenticated using(public.kann_vertragsversand_ausfuehren());
revoke all on function public.prepare_contract_dispatch(bigint,bigint),public.create_contract_redispatch(bigint),public.claim_contract_dispatch(bigint),public.kann_vertragsversand_ausfuehren(),public.resolve_vertragsversand_berechtigte(date) from public,anon;
grant execute on function public.prepare_contract_dispatch(bigint,bigint),public.create_contract_redispatch(bigint),public.claim_contract_dispatch(bigint),public.kann_vertragsversand_ausfuehren() to authenticated,service_role;
